import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.CiQ1TEvV.js";const m=JSON.parse('{"title":"TUI Commands","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tui-commands.md","filePath":"guide/tui-commands.md","lastUpdated":1785115728000}'),i={name:"guide/tui-commands.md"};function n(o,t,r,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="tui-commands" tabindex="-1">TUI Commands <a class="header-anchor" href="#tui-commands" aria-label="Permalink to &quot;TUI Commands&quot;">​</a></h1><p>Mneme&#39;s Rich-based terminal UI supports slash commands and keyboard shortcuts.</p><h2 id="slash-commands" tabindex="-1">Slash Commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/help</code></td><td>Show all commands</td></tr><tr><td><code>/files</code></td><td>Add, remove, list, watch, or stop watching files</td></tr><tr><td><code>/mode</code></td><td>Toggle Standard RAG / Graph RAG</td></tr><tr><td><code>/alpha</code></td><td>Set the Graph RAG fusion weight</td></tr><tr><td><code>/settings</code></td><td>View or change API settings</td></tr><tr><td><code>/models</code></td><td>List available models</td></tr><tr><td><code>/status</code></td><td>Show index and service status</td></tr><tr><td><code>/clear</code></td><td>Clear chat history</td></tr><tr><td><code>/quit</code></td><td>Exit</td></tr></tbody></table><h2 id="file-management-examples" tabindex="-1">File Management Examples <a class="header-anchor" href="#file-management-examples" aria-label="Permalink to &quot;File Management Examples&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/files watch /path/to/directory</span></span>
<span class="line"><span>/files list</span></span>
<span class="line"><span>/files stop</span></span>
<span class="line"><span>/files add /path/to/file.pdf</span></span>
<span class="line"><span>/files remove /path/to/file.pdf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+P</code></td><td>Open command palette</td></tr><tr><td><code>Ctrl+L</code></td><td>Toggle sidebar</td></tr><tr><td><code>Ctrl+N</code></td><td>New session</td></tr><tr><td><code>Ctrl+K</code></td><td>Clear chat</td></tr><tr><td><code>Ctrl+C</code></td><td>Exit</td></tr></tbody></table><h2 id="mode-switching" tabindex="-1">Mode Switching <a class="header-anchor" href="#mode-switching" aria-label="Permalink to &quot;Mode Switching&quot;">​</a></h2><p>Use <code>/mode</code> to switch between Standard RAG and Graph RAG. When switching to Graph RAG from Standard, Mneme will:</p><ol><li>Show a confirmation prompt</li><li>Build the knowledge graph from the current index (with a progress bar)</li><li>Switch the retrieval mode</li></ol><p>When switching back to Standard RAG, the mode changes immediately without rebuilding.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Use <code>/settings</code> to view and modify:</p><ul><li>API Key (masked for security)</li><li>Base URL</li><li>LLM Model</li><li>Temperature</li><li>Top-K Min / Max</li><li>Alpha (Graph RAG weight)</li></ul><p>All changes are persisted to <code>.env</code> and take effect immediately.</p>`,16)])])}const u=e(i,[["render",n]]);export{m as __pageData,u as default};
